print_context() {
    printf '%s\n' \
        "OVERALL_STAGE=${OVERALL_STAGE}" \
        "LANE=${LANE}" \
        "LANE_BRANCH=${LANE_BRANCH}" \
        "CURRENT_TOPIC=${CURRENT_TOPIC}" \
        "CURRENT_STAGE=${CURRENT_STAGE}" \
        "NEXT_STAGE=${NEXT_STAGE}" \
        "LANE_PROGRESS=${LANE_PROGRESS}"
}

set_stage() {
    CURRENT_STAGE="$1"
    NEXT_STAGE="$2"
}

section() {
    printf '\n===== %s =====\n' "$1"
    print_context
}

pass() {
    printf 'PASS: %s\n' "$1"
    print_context
}

warn() {
    warning_count=$((warning_count + 1))
    printf 'WARN: %s\n' "$1"
    print_context
}

fail() {
    failure_count=$((failure_count + 1))
    final_rc=1
    printf 'FAIL: %s\n' "$1"
    print_context
}

is_allowed_preexisting_status_path() {
    local candidate="$1"
    [ "$candidate" = "$SELF_REL" ] || \
    [ "$candidate" = "$OBSOLETE_AUDIT_REL" ] || \
    [ "$candidate" = "$OBSOLETE_SW05_V1_REL" ]
}

is_commit_path() {
    local candidate="$1"
    local allowed
    for allowed in "${COMMIT_PATHS[@]}"; do
        [ "$candidate" = "$allowed" ] && return 0
    done
    return 1
}

sha256_file() {
    sha256sum "$1" | awk '{print $1}'
}

restore_exact_checkpoint_deletion() {
    local status_line

    status_line="$(git status --porcelain=v1 -- "$CHECKPOINT_SCRIPT_REL")"

    if [ -z "$status_line" ]; then
        pass "checkpoint/worktree creation script matches HEAD"
        return 0
    fi

    if [ "$status_line" != " D $CHECKPOINT_SCRIPT_REL" ]; then
        fail "checkpoint script has an unexpected state and will not be changed automatically: $status_line"
        return 1
    fi

    if ! git cat-file -e "HEAD:$CHECKPOINT_SCRIPT_REL" 2>/dev/null; then
        fail "checkpoint script is not present in HEAD and cannot be restored safely"
        return 1
    fi

    if ! git diff --cached --quiet -- "$CHECKPOINT_SCRIPT_REL"; then
        fail "checkpoint script has a staged change; automatic restoration is prohibited"
        return 1
    fi

    if [ -e "$CHECKPOINT_SCRIPT_REL" ] || [ -L "$CHECKPOINT_SCRIPT_REL" ]; then
        fail "checkpoint script status says deleted but a filesystem object exists"
        return 1
    fi

    if git restore --source=HEAD --worktree -- "$CHECKPOINT_SCRIPT_REL"; then
        pass "restored the exact pre-existing unstaged checkpoint-script deletion to HEAD"
    else
        fail "failed to restore the exact checkpoint-script deletion"
        return 1
    fi

    if git status --porcelain=v1 -- "$CHECKPOINT_SCRIPT_REL" | grep -q .; then
        fail "checkpoint script is still changed after restoration"
        return 1
    fi

    pass "checkpoint script restoration leaves no diff and will not enter the SW-05 commit"
}

rollback_uncommitted_authoring() {
    [ "$commit_created" -eq 0 ] || return 0
    [ "$installation_started" -eq 1 ] || return 0

    git reset -q -- "${COMMIT_PATHS[@]}" 2>/dev/null || true

    local rel backup
    for rel in "${TARGETS[@]}"; do
        backup="$backup_root/$rel"
        if [ -e "$backup" ] || [ -L "$backup" ]; then
            mkdir -p -- "$(dirname "$REPO_DIR/$rel")" 2>/dev/null || true
            cp -a -- "$backup" "$REPO_DIR/$rel" 2>/dev/null || true
        else
            rm -f -- "$REPO_DIR/$rel" 2>/dev/null || true
        fi
    done

    find "$REPO_DIR/scripts" -maxdepth 1 -type d -name '__pycache__' -empty -delete 2>/dev/null || true
    printf 'ROLLBACK_COMPLETED=true\n'
    print_context
}

cleanup() {
    local shell_rc=$?
    rm -rf -- "$python_cache_dir" 2>/dev/null || true

    if [ "$final_rc" -ne 0 ] || [ "$shell_rc" -ne 0 ]; then
        rollback_uncommitted_authoring
    fi

    [ -n "$backup_root" ] && rm -rf -- "$backup_root" 2>/dev/null || true
}

trap cleanup EXIT

write_b64() {
    local rel="$1"
    local payload="$2"
    local target="$REPO_DIR/$rel"
    local temp

    mkdir -p -- "$(dirname "$target")" || {
        fail "mkdir failed: $rel"
        return 1
    }

    temp="$(mktemp "${target}.tmp.XXXXXX")" || {
        fail "temporary file creation failed: $rel"
        return 1
    }

    if ! printf '%s' "$payload" | base64 -d >"$temp"; then
        rm -f -- "$temp"
        fail "base64 decode failed: $rel"
        return 1
    fi

    if ! mv -f -- "$temp" "$target"; then
        rm -f -- "$temp"
        fail "install failed: $rel"
        return 1
    fi

    pass "authored $rel"
}

sw05_commit_is_complete() {
    local commit
    commit="$(
        git log --format='%H%x09%s' --all |
        awk -F '\t' -v subject="$COMMIT_SUBJECT" '$2 == subject {print $1; exit}'
    )"

    [ -n "$commit" ] || return 1
    git merge-base --is-ancestor "$commit" HEAD >/dev/null 2>&1 || return 1

    local rel
    for rel in "${TARGETS[@]}"; do
        git ls-tree -r --name-only "$commit" -- "$rel" | grep -Fxq "$rel" || return 1
        [ -f "$REPO_DIR/$rel" ] || return 1
        git status --porcelain=v1 -- "$rel" | grep -q . && return 1
    done

    printf '%s' "$commit"
}

validate_source_schema() {
    python3 - "$REPO_DIR" "$TOPIC_ID" <<'PY_SCHEMA'
from __future__ import annotations

import json
import sys
from pathlib import Path

root = Path(sys.argv[1])
topic_id = sys.argv[2]
pack = root / "rubrics" / "topic_packs" / topic_id

def load(name: str) -> dict:
    return json.loads((pack / name).read_text(encoding="utf-8"))

fact = load("fact_anchor.json")
logic = load("logic_check.json")
model = load("model_answer.json")
importance = load("topic_importance.json")

for name, data in {
    "fact_anchor.json": fact,
    "logic_check.json": logic,
    "model_answer.json": model,
    "topic_importance.json": importance,
}.items():
    assert isinstance(data, dict), name
    assert data.get("topic_id") == topic_id, (name, data.get("topic_id"))

fact_required = {
    "schema_version", "topic_id", "title_ko", "question_type_hint",
    "anchors", "fatal_wrong_claims", "safe_expressions",
}
assert fact_required <= set(fact), sorted(fact_required - set(fact))
assert fact["schema_version"] == "fact_anchor.v1"
assert len(fact["anchors"]) == 30
assert len(fact["fatal_wrong_claims"]) == 16
assert len(fact["safe_expressions"]) >= 16

anchor_required = {
    "id", "anchor_id", "statement", "importance", "keywords", "core_terms",
    "accepted_explanations", "rejected_explanations", "grading_notes",
    "source_basis", "claim", "description",
}
for index, row in enumerate(fact["anchors"]):
    assert anchor_required <= set(row), (index, sorted(anchor_required - set(row)))
    assert row["id"] == row["anchor_id"]
    assert row["statement"] == row["claim"] == row["description"]
    assert row["keywords"] and row["core_terms"]
    assert row["accepted_explanations"]
    assert row["source_basis"]

fatal_required = {
    "id", "claim", "correction", "wrong_claim", "correct_rule", "severity",
    "affected_layers", "message", "description", "grading_notes",
}
for index, row in enumerate(fact["fatal_wrong_claims"]):
    assert fatal_required <= set(row), (index, sorted(fatal_required - set(row)))
    assert row["severity"] == "fatal"
    assert row["affected_layers"] == ["C"]

logic_required = {
    "schema_version", "topic_id", "title", "deterministic_checks",
    "llm_profile",
}
assert logic_required <= set(logic), sorted(logic_required - set(logic))
assert logic["schema_version"] == "topic_pack.logic_check.v1"
det = logic["deterministic_checks"]
assert det["enabled"] is False
for key in ("fatal_checks", "major_checks", "question_type_checks"):
    assert det[key] == []
profile = logic["llm_profile"]
assert profile["enabled"] is True
assert profile["candidate_extraction"]["rules"] == []
assert profile["score_policy"]["direct_score_application"] is False
assert profile["score_policy"]["direct_d_e_effect"] == "none"
assert profile["score_policy"]["affected_layers"] == ["C"]
assert len(profile["truth_schema"]) == len(fact["anchors"])
assert len(profile["fatal_conditions"]) == len(fact["fatal_wrong_claims"])
assert len(profile["major_checks"]) == 12
assert len(profile["false_positive_cautions"]) >= 10

model_required = {
    "schema_version", "topic_id", "title_ko", "question_type",
    "expected_question_patterns", "recommended_outline", "high_score_points",
    "common_missing_points", "routing_aliases", "routing_field_points",
}
assert model_required <= set(model), sorted(model_required - set(model))
assert model["schema_version"] == "topic_pack.model_answer.v1"
assert model["question_type"] == "PRINCIPLE_INTERPRETATION"
assert len(model["expected_question_patterns"]) == 10
assert len(model["recommended_outline"]) == 8
assert len(model["routing_aliases"]) == 14

anchor_ids = {row["id"] for row in fact["anchors"]}
for row in model["expected_question_patterns"]:
    assert set(row["required_anchor_ids"]) <= anchor_ids
outline_union: set[str] = set()
for row in model["recommended_outline"]:
    refs = set(row["anchor_refs"])
    assert refs <= anchor_ids
    outline_union.update(refs)
assert outline_union == anchor_ids

importance_required = {
    "schema_version", "topic_id", "difficulty", "selection_importance",
    "question_type", "high_band_unlock_conditions", "note",
}
assert importance_required <= set(importance), sorted(importance_required - set(importance))
assert importance["schema_version"] == "topic_pack.topic_importance.v1"
assert importance["difficulty"] == "THEORY_CORE"
assert importance["selection_importance"] == "CORE_MUST_PREPARE"
assert importance["question_type"] == "PRINCIPLE_INTERPRETATION"
assert len(importance["high_band_unlock_conditions"]) >= 8

fatal_ids = {row["id"] for row in fact["fatal_wrong_claims"]}
for required in {
    "certified_product_auto_sil",
    "proof_test_equals_validation",
    "different_cpu_guarantees_independence",
    "diversity_eliminates_ccf",
    "software_random_failure_rate_only",
    "bypass_no_sil_effect",
}:
    assert required in fatal_ids, required

print("TOPIC_PACK_SCHEMA_VALIDATION=PASS")
print(f"ANCHORS={len(fact['anchors'])}")
print(f"FATALS={len(fact['fatal_wrong_claims'])}")
print(f"MAJORS={len(profile['major_checks'])}")
print(f"ALIASES={len(model['routing_aliases'])}")
PY_SCHEMA
}

validate_ownership_diff() {
    local base_ref merge_base rel
    if git rev-parse --verify --quiet "${REMOTE}/main" >/dev/null; then
        base_ref="${REMOTE}/main"
    elif git rev-parse --verify --quiet main >/dev/null; then
        base_ref="main"
    else
        fail "origin/main and local main are unavailable for Lane ownership audit"
        return 1
    fi

    merge_base="$(git merge-base HEAD "$base_ref")" || {
        fail "cannot compute merge-base against $base_ref"
        return 1
    }

    printf 'OWNERSHIP_BASE_REF=%s\n' "$base_ref"
    printf 'OWNERSHIP_MERGE_BASE=%s\n' "$merge_base"
    printf 'LANE_BRANCH_CHANGED_PATHS_BEGIN\n'

    while IFS= read -r rel; do
        [ -n "$rel" ] || continue
        printf '%s\n' "$rel"
        if ! is_commit_path "$rel"; then
            fail "Lane C branch contains a path outside the SW-05 commit allowance: $rel"
        fi
    done < <(git diff --name-only "$merge_base"..HEAD)

    printf 'LANE_BRANCH_CHANGED_PATHS_END\n'

    if git diff --quiet "$merge_base"..HEAD -- rubrics/generated/; then
        pass "rubrics/generated/** unchanged on Lane C branch"
    else
        fail "rubrics/generated/** changed on Lane C branch"
    fi

    [ "$failure_count" -eq 0 ]
}

main() {
    section "0. normalize invocation and verify immutable Lane C contract"

    local invocation_abs script_abs script_dir normalized_abs git_top branch
    invocation_abs="$(pwd -P 2>/dev/null || pwd)"
    script_abs="$(realpath "${BASH_SOURCE[0]}")"
    script_dir="$(dirname "$script_abs")"

    printf '%s\n' \
        "INVOCATION_ABSOLUTE_PATH=${invocation_abs}" \
        "SCRIPT_ABSOLUTE_PATH=${script_abs}" \
        "EXPECTED_SCRIPT_DIR=${EXPECTED_SCRIPT_DIR}" \
        "REPO_DIR=${REPO_DIR}" \
        "EXPECTED_BRANCH=${LANE_BRANCH}" \
        "REMOTE=${REMOTE}" \
        "MAIN_WORKTREE_PROHIBITED=/home/now0930/hermes/workspace/prof_eng_answer" \
        "LANE_A_WORKTREE_PROHIBITED=/home/now0930/hermes/workspace/prof_eng_answer_sw_lane_a" \
        "LANE_B_WORKTREE_PROHIBITED=/home/now0930/hermes/workspace/prof_eng_answer_sw_lane_b" \
        "GENERATED_REBUILD=false" \
        "VALIDATE_ALL=false" \
        "RELEASE_VALIDATION=false" \
        "EXTERNAL_LLM_VALIDATION=false" \
        "PUSH=false" \
        "CHECKPOINT_DELETION_REPAIR=EXACT_UNSTAGED_RESTORE_ONLY"
    print_context

    if [ "$script_dir" = "$EXPECTED_SCRIPT_DIR" ]; then
        pass "script is placed in the Lane C gemini_script directory"
    else
        fail "script directory mismatch: expected=$EXPECTED_SCRIPT_DIR actual=$script_dir"
        return 1
    fi

    if [ "$(basename "$script_abs")" = "$SELF_NAME" ]; then
        pass "script filename matches the committed Lane C contract"
    else
        fail "script filename mismatch: expected=$SELF_NAME actual=$(basename "$script_abs")"
        return 1
    fi

    if [ ! -d "$REPO_DIR" ]; then
        fail "Lane C repository directory does not exist"
        return 1
    fi

    cd "$REPO_DIR" || {
        fail "cannot enter Lane C repository"
        return 1
    }

    normalized_abs="$(pwd -P)"
    printf 'NORMALIZED_CURRENT_ABSOLUTE_PATH=%s\n' "$normalized_abs"
    if [ "$normalized_abs" = "$REPO_DIR" ]; then
        pass "current absolute path exactly matches Lane C REPO_DIR before mutation"
    else
        fail "normalized current path does not match Lane C REPO_DIR"
        return 1
    fi

    case "$normalized_abs" in
        "/home/now0930/hermes/workspace/prof_eng_answer"|\
        "/home/now0930/hermes/workspace/prof_eng_answer_sw_lane_a"|\
        "/home/now0930/hermes/workspace/prof_eng_answer_sw_lane_b")
            fail "prohibited integration or other-lane worktree selected"
            return 1
            ;;
        *)
            pass "main and Lane A/B worktrees are excluded"
            ;;
    esac

    if git rev-parse --is-inside-work-tree >/dev/null 2>&1; then
        pass "normal Git worktree detected"
    else
        fail "not a Git worktree"
        return 1
    fi

    git_top="$(git rev-parse --show-toplevel 2>/dev/null || true)"
    printf 'GIT_TOPLEVEL=%s\n' "$git_top"
    if [ "$git_top" = "$REPO_DIR" ]; then
        pass "Git top-level exactly matches Lane C REPO_DIR"
    else
        fail "Git top-level mismatch"
        return 1
    fi

    branch="$(git branch --show-current 2>/dev/null || true)"
    printf 'CURRENT_BRANCH=%s\n' "$branch"
    if [ "$branch" = "$LANE_BRANCH" ]; then
        pass "current branch exactly matches Lane C branch"
    else
        fail "branch mismatch: expected=$LANE_BRANCH actual=$branch"
        return 1
    fi

    if git remote get-url "$REMOTE" >/dev/null 2>&1; then
        printf 'REMOTE_URL=%s\n' "$(git remote get-url "$REMOTE")"
        pass "remote origin exists"
    else
        fail "remote origin is missing"
        return 1
    fi

    section "1. detect an existing complete SW-05 commit"

    local existing_commit
    existing_commit="$(sw05_commit_is_complete || true)"
    if [ -n "$existing_commit" ]; then
        set_stage "SW05_ALREADY_COMMITTED" "SW11_AUTHORING"
        CURRENT_TOPIC="SW-11 historian_mes_it_ot_integration_industrial_data_quality_realtime_processing"
        LANE_PROGRESS="1/4"
        printf '%s\n' \
            "SW05_STATE=COMMITTED_CLEAN" \
            "DECISION=DO_NOT_REWRITE_SW05" \
            "COMMIT_HASH=${existing_commit}" \
            "COMMIT_SUBJECT=$(git log -1 --pretty=%s "$existing_commit")" \
            "VALIDATION_RESULT=EXISTING_SW05_COMMIT_ACCEPTED" \
            "NEXT_TOPIC=${CURRENT_TOPIC}" \
            "PUSH_PERFORMED=false"
        pass "SW-05 is already committed cleanly; proceed to SW-11"
        return 0
    fi

    set_stage "SW05_AUTHORING_PREFLIGHT" "SW05_SOURCE_AUTHORING"
    CURRENT_TOPIC="SW-05 ${TOPIC_ID}"
    LANE_PROGRESS="0/4"

    section "2. verify clean pre-mutation ownership baseline"

    if git diff --cached --quiet; then
        pass "staging area is empty"
    else
        fail "staging area contains pre-existing changes"
    fi

    if [ "$failure_count" -eq 0 ]; then
        restore_exact_checkpoint_deletion || true
    fi

    printf 'PREEXISTING_STATUS_BEGIN\n'
    local status_line status_path
    while IFS= read -r status_line; do
        [ -n "$status_line" ] || continue
        printf '%s\n' "$status_line"
        status_path="${status_line:3}"
        if ! is_allowed_preexisting_status_path "$status_path"; then
            fail "pre-existing worktree change is outside the approved Lane C bootstrap script paths: $status_path"
        fi
    done < <(git status --porcelain=v1 -uall)
    printf 'PREEXISTING_STATUS_END\n'

    local rel
    for rel in "${TARGETS[@]}"; do
        if [ -e "$rel" ] || [ -L "$rel" ]; then
            fail "SW-05 target already exists without an accepted complete commit: $rel"
        fi
    done

    if git status --porcelain=v1 -- rubrics/generated/ | grep -q .; then
        fail "rubrics/generated/** has a pre-existing worktree change"
    else
        pass "rubrics/generated/** has no worktree change"
    fi

    [ "$failure_count" -eq 0 ] || return 1

    backup_root="$(mktemp -d "${TMPDIR:-/tmp}/sw05_backup.XXXXXX")" || {
        fail "cannot create SW-05 backup directory"
        return 1
    }

    installation_started=1

    set_stage "SW05_SOURCE_AUTHORING" "SW05_JSON_AND_SCHEMA_VALIDATION"
    section "3. author the complete SW-05 source Topic Pack"
write_b64 "docs/topic_sheets/sis_sil_safety_software_independence_systematic_failure_verification_validation.md" ""
write_b64 "rubrics/topic_packs/sis_sil_safety_software_independence_systematic_failure_verification_validation/README.md" ""
write_b64 "rubrics/topic_packs/sis_sil_safety_software_independence_systematic_failure_verification_validation/fact_anchor.json" ""
write_b64 "rubrics/topic_packs/sis_sil_safety_software_independence_systematic_failure_verification_validation/logic_check.json" ""
write_b64 "rubrics/topic_packs/sis_sil_safety_software_independence_systematic_failure_verification_validation/model_answer.json" ""
write_b64 "rubrics/topic_packs/sis_sil_safety_software_independence_systematic_failure_verification_validation/topic_importance.json" ""
write_b64 "scripts/test_sis_sil_safety_software_topic.py" ""

    [ "$failure_count" -eq 0 ] || return 1

    chmod +x "$TEST_REL" || {
        fail "cannot set focused test executable permission"
        return 1
    }

    set_stage "SW05_JSON_AND_SCHEMA_VALIDATION" "SW05_FOCUSED_VALIDATION"
    section "4. validate JSON syntax and Topic Pack schema"

    for rel in "${JSON_PATHS[@]}"; do
        if python3 -m json.tool "$rel" >/dev/null; then
            pass "JSON syntax: $rel"
        else
            fail "JSON syntax: $rel"
        fi
    done

    if validate_source_schema; then
        pass "focused Topic Pack schema contract"
    else
        fail "focused Topic Pack schema contract"
    fi

    for rel in "${TARGETS[@]}"; do
        actual_sha="$(sha256_file "$rel")"
        expected_sha="${EXPECTED_SHA256[$rel]}"
        printf 'SOURCE_SHA256=%s|%s\n' "$rel" "$actual_sha"
        if [ "$actual_sha" = "$expected_sha" ]; then
            pass "reviewed source payload hash: $rel"
        else
            fail "source payload hash mismatch: $rel"
        fi
    done

    [ "$failure_count" -eq 0 ] || return 1

    set_stage "SW05_FOCUSED_VALIDATION" "SW05_OWNERSHIP_VALIDATION"
    section "5. run focused validation without external LLM"

    if python3 -m py_compile "$TEST_REL"; then
        pass "py_compile changed focused-test Python only"
    else
        fail "py_compile focused test"
    fi

    if python3 "$TEST_REL"; then
        pass "SW-05 focused regression"
    else
        fail "SW-05 focused regression"
    fi

    rm -rf -- "$python_cache_dir" 2>/dev/null || true

    printf '%s\n' \
        "SEMANTIC_VALIDATION=PASS_BY_CHATGPT_AUTHORING_REVIEW" \
        "SEMANTIC_SCOPE=SIL_AS_SIF_PROPERTY,SYSTEMATIC_VS_RANDOM,VERIFICATION_VS_VALIDATION,INDEPENDENCE,PROOF_TEST_BOUNDARY" \
        "EXTERNAL_LLM_VALIDATION_RUN=false"
    pass "ChatGPT-authored semantic guard contract is embedded in Anchor, Fatal, Major and false-positive records"

    [ "$failure_count" -eq 0 ] || return 1

    set_stage "SW05_OWNERSHIP_VALIDATION" "SW05_LOCAL_COMMIT"
    section "6. validate diff, hashes and Lane C ownership"

    if git diff --check -- "${TARGETS[@]}"; then
        pass "git diff --check for SW-05 source files"
    else
        fail "git diff --check for SW-05 source files"
    fi

    if python3 - "$REPO_DIR" "${TARGETS[@]}" "$SELF_REL" <<'PY_TEXT'
from pathlib import Path
import sys

root = Path(sys.argv[1])
problems: list[str] = []
for relative in sys.argv[2:]:
    path = root / relative
    text = path.read_text(encoding="utf-8")
    if not text.endswith("\n"):
        problems.append(f"{relative}: missing final newline")
    for number, line in enumerate(text.splitlines(), start=1):
        if line.rstrip(" \t") != line:
            problems.append(f"{relative}:{number}: trailing whitespace")
if problems:
    raise SystemExit("\n".join(problems))
print("TEXT_QUALITY_VALIDATION=PASS")
PY_TEXT
    then
        pass "UTF-8 text, trailing-whitespace and final-newline checks"
    else
        fail "text quality checks"
    fi

    printf 'AUTHORING_STATUS_BEGIN\n'
    while IFS= read -r status_line; do
        [ -n "$status_line" ] || continue
        printf '%s\n' "$status_line"
        status_path="${status_line:3}"
        if ! is_commit_path "$status_path" && ! is_allowed_preexisting_status_path "$status_path"; then
            fail "authoring changed a path outside Lane C SW-05 ownership: $status_path"
        fi
    done < <(git status --porcelain=v1 -uall)
    printf 'AUTHORING_STATUS_END\n'

    if git status --porcelain=v1 -- rubrics/generated/ | grep -q .; then
        fail "rubrics/generated/** changed during SW-05 authoring"
    else
        pass "rubrics/generated/** unchanged during SW-05 authoring"
    fi

    [ "$failure_count" -eq 0 ] || return 1

    section "7. create the SW-05 local Topic commit"

    git add -- "${COMMIT_PATHS[@]}" || {
        fail "git add failed for SW-05 commit paths"
        return 1
    }

    mapfile -t staged_paths < <(git diff --cached --name-only | LC_ALL=C sort)
    mapfile -t expected_paths < <(printf '%s\n' "${COMMIT_PATHS[@]}" | LC_ALL=C sort)

    printf 'STAGED_PATHS_BEGIN\n'
    printf '%s\n' "${staged_paths[@]}"
    printf 'STAGED_PATHS_END\n'

    if [ "${#staged_paths[@]}" -ne "${#expected_paths[@]}" ]; then
        fail "staged path count differs from exact SW-05 commit contract"
    else
        local index
        for index in "${!expected_paths[@]}"; do
            if [ "${staged_paths[$index]}" != "${expected_paths[$index]}" ]; then
                fail "staged path mismatch: expected=${expected_paths[$index]} actual=${staged_paths[$index]}"
            fi
        done
    fi

    if git diff --cached --check; then
        pass "staged diff check"
    else
        fail "staged diff check"
    fi

    [ "$failure_count" -eq 0 ] || return 1

    if git commit -m "$COMMIT_SUBJECT"; then
        commit_created=1
        installation_started=0
        pass "SW-05 local Topic commit created"
    else
        fail "SW-05 local Topic commit failed"
        return 1
    fi

    local commit_hash commit_subject
    commit_hash="$(git rev-parse HEAD)"
    commit_subject="$(git log -1 --pretty=%s)"

    if [ "$commit_subject" = "$COMMIT_SUBJECT" ]; then
        pass "commit subject matches SW-05 contract"
    else
        fail "commit subject mismatch"
    fi

    printf 'COMMITTED_FILES_BEGIN\n'
    mapfile -t committed_paths < <(git diff-tree --no-commit-id --name-only -r HEAD | LC_ALL=C sort)
    printf '%s\n' "${committed_paths[@]}"
    printf 'COMMITTED_FILES_END\n'

    if [ "${#committed_paths[@]}" -ne "${#expected_paths[@]}" ]; then
        fail "committed path count differs from exact SW-05 contract"
    else
        for index in "${!expected_paths[@]}"; do
            if [ "${committed_paths[$index]}" != "${expected_paths[$index]}" ]; then
                fail "committed path mismatch: expected=${expected_paths[$index]} actual=${committed_paths[$index]}"
            fi
        done
    fi

    local obsolete_rel
    for obsolete_rel in "$OBSOLETE_AUDIT_REL" "$OBSOLETE_SW05_V1_REL"; do
        if [ -e "$obsolete_rel" ] && ! git ls-files --error-unmatch -- "$obsolete_rel" >/dev/null 2>&1; then
            rm -f -- "$obsolete_rel" || {
                fail "cannot remove obsolete untracked Lane C script: $obsolete_rel"
                continue
            }
            pass "obsolete untracked Lane C script removed after successful SW-05 commit: $obsolete_rel"
        fi
    done

    set_stage "SW05_POST_COMMIT_VALIDATION" "SW11_AUTHORING"
    section "8. validate the committed Lane C state"

    if git status --porcelain=v1 | grep -q .; then
        printf 'POST_COMMIT_STATUS_BEGIN\n'
        git status --short --branch
        printf 'POST_COMMIT_STATUS_END\n'
        fail "working tree is not clean after the SW-05 commit"
    else
        pass "working tree is clean after the SW-05 commit"
    fi

    if validate_ownership_diff; then
        pass "Lane C ownership boundary after SW-05 commit"
    fi

    if git log -1 --format='%H%x09%s' | grep -Fq "$commit_hash"$'\t'"$COMMIT_SUBJECT"; then
        pass "HEAD is the expected SW-05 Topic commit"
    else
        fail "HEAD does not match the expected SW-05 Topic commit"
    fi

    [ "$failure_count" -eq 0 ] || return 1

    CURRENT_TOPIC="SW-11 historian_mes_it_ot_integration_industrial_data_quality_realtime_processing"
    CURRENT_STAGE="SW05_COMMITTED_AND_VALIDATED"
    NEXT_STAGE="SW11_AUTHORING"
    LANE_PROGRESS="1/4"

    section "9. SW-05 completion report"

    printf '%s\n' \
        "LANE=${LANE}" \
        "SW_NUMBER=SW-05" \
        "TOPIC_ID=${TOPIC_ID}" \
        "COMMIT_HASH=${commit_hash}" \
        "COMMIT_SUBJECT=${commit_subject}" \
        "VALIDATION_RESULT=PASS" \
        "JSON_SYNTAX=PASS" \
        "TOPIC_PACK_SCHEMA=PASS" \
        "FOCUSED_TEST=PASS" \
        "PY_COMPILE=PASS_FOCUSED_TEST_ONLY" \
        "GIT_DIFF_CHECK=PASS" \
        "LANE_C_OWNERSHIP=PASS" \
        "WORKING_TREE_CLEAN=true" \
        "GENERATED_BANK_CHANGED=false" \
        "EXTERNAL_LLM_VALIDATION_RUN=false" \
        "PUSH_PERFORMED=false" \
        "REMOTE_PUSH_DEFERRED_UNTIL_LANE_PROGRESS_4_OF_4=true" \
        "NEXT_TOPIC=${CURRENT_TOPIC}" \
        "LANE_PROGRESS=${LANE_PROGRESS}"
    print_context

    return 0
}

main || final_rc=$?

(return "$final_rc" 2>/dev/null) || [ "$final_rc" -eq 0 ]
